/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK freeMenuItemRecord(s32);                         /* extern */
M2C_UNK freeMenuMarkers();                            /* extern */

/* Frees the menu item record held in the slot, clears the slot and frees the menu markers. */ void releaseMenuItemRecord(s32 *recordSlot) {
    s32 record;

    record = *recordSlot;
    if (record != 0) {
        freeMenuItemRecord(record);
        *recordSlot = 0;
        freeMenuMarkers();
    }
}
